<form class="filter-bar" method="get" action="<?= $escape($indexUrl) ?>"><label>Search<input name="q" value="<?= $escape($filters['q']) ?>"></label><label>Stage<select name="stage"><option value="">All stages</option><?php foreach($stages as $key=>$label):?><option value="<?= $escape($key) ?>"<?= $filters['stage']===$key?' selected':'' ?>><?= $escape($label) ?></option><?php endforeach;?></select></label><label>Offer<select name="offer"><option value="">All offers</option><?php foreach($offers as $key=>$label):?><option value="<?= $escape($key) ?>"<?= $filters['offer']===$key?' selected':'' ?>><?= $escape($label) ?></option><?php endforeach;?></select></label><button>Apply</button><a href="<?= $escape($indexUrl) ?>">Clear</a></form><p><?= $escape($count) ?> result<?= $count===1?'':'s' ?>.</p>
<header class="page-header"><div><p class="eyebrow">Commercial pipeline</p><h1>Opportunities</h1></div></header><?php if($opportunities===[]):?><p>No opportunities yet. Qualify a prospect before adding one.</p><?php else:?><table><thead><tr><th>Relationship</th><th>Stage</th><th>Value</th><th>Expected close</th><th>Next action</th></tr></thead><tbody><?php foreach($opportunities as $o):?><tr><td><a href="<?= $escape($showUrl((int)$o['id'])) ?>"><?= $escape($o['company_name']?:$o['contact_name']) ?></a></td><td><?= $escape($stages[$o['stage']]??$o['stage']) ?></td><td>$<?= $escape($o['value_amount']) ?></td><td><?= $escape($o['expected_close_on']??'—') ?></td><td><?= $escape($o['follow_up_action']??'—') ?></td></tr><?php endforeach;?></tbody></table><?php endif;?>
<?php if($pages>1):?><nav class="tab-list" aria-label="Opportunity pages"><?php for($number=1;$number<=$pages;$number++):?><a href="<?= $escape($indexUrl.'?q='.rawurlencode($filters['q']).'&stage='.rawurlencode($filters['stage']).'&offer='.rawurlencode($filters['offer']).'&page='.$number) ?>"<?= $number===$page?' aria-current="page"':'' ?>><?= $escape($number) ?></a><?php endfor;?></nav><?php endif;?>
